#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> L(N);
    long long C = 0;
    for (int i = 0; i < N; ++i) {
        cin >> L[i];
        C += L[i];
    }

    if (C % 2 != 0) {
        cout << "N\n";
        return 0;
    }

    long long half = C / 2;

    vector<long long> pos(N);
    pos[0] = 0;
    for (int i = 1; i < N; ++i) {
        pos[i] = pos[i - 1] + L[i - 1];
    }

    int count = 0;
    for (int i = 0; i < N; ++i) {
        long long target = pos[i] + half;
        if (target >= C) target -= C;

        if (binary_search(pos.begin(), pos.end(), target)) {
            ++count;
        }
    }

    if (count / 2 >= 2) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
